"""Generate the theme's asset support lists from the audited Drive manifest."""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[1]
manifest = json.loads((ROOT/'staging/overnight-asset-manifest.json').read_text())
pilot = ['Banana','Blueberry','Mango','Pineapple','Watermelon']
manifest.sort(key=lambda x: (0,pilot.index(x['flavor'])) if x['flavor'] in pilot else (1,x['flavor']))
all_names = ','.join(x['flavor'] for x in manifest)
interactive = ','.join(x['flavor'] for x in manifest if x.get('left') and x.get('right') and x['flavor'] != 'Beet Root')
(ROOT/'snippets/hx-flavor-support.liquid').write_text("{%- comment -%}Generated by scripts/configure_catalog_theme.py; real exported artwork only.{%- endcomment -%}\n{%- if mode == 'interactive' -%}"+interactive+"{%- else -%}"+all_names+"{%- endif -%}\n")
p = ROOT/'sections/product-seamoss.liquid'
s = p.read_text(encoding='utf-8')
s = s.replace("  assign pilot_flavors = 'Banana,Blueberry,Mango,Pineapple,Watermelon' | split: ','", "  capture supported_flavors\n    render 'hx-flavor-support'\n  endcapture\n  assign pilot_flavors = supported_flavors | strip | split: ','\n  capture interactive_flavors\n    render 'hx-flavor-support', mode: 'interactive'\n  endcapture\n  assign jar_flavors = interactive_flavors | strip | split: ','")
s = s.replace('unless pilot_flavors contains initial_variant.option1 %} hidden', 'unless jar_flavors contains initial_variant.option1 %} hidden')
s = s.replace("value == 'Banana' or value == 'Blueberry' or value == 'Mango' or value == 'Pineapple' or value == 'Watermelon'", 'pilot_flavors contains value')
s = s.replace("| downcase | prepend: 'hx-pilot-'", "| handleize | prepend: 'hx-pilot-'")
s = s.replace('Enable five-flavor 360° jar viewer','Enable 360° jar viewer').replace('Loads on click. Other flavors keep their photo galleries. Label artwork is pending final approval.','Loads on click for flavors with prepared front and side labels. Other flavors keep their photo galleries.')
p.write_text(s,encoding='utf-8')
p=ROOT/'snippets/hx-pilot-gallery.liquid'
s=p.read_text().replace("{%- assign pilot_flavors = 'Banana,Blueberry,Mango,Pineapple,Watermelon' | split: ',' -%}","{%- capture supported_flavors -%}{%- render 'hx-flavor-support' -%}{%- endcapture -%}\n{%- assign pilot_flavors = supported_flavors | strip | split: ',' -%}\n{%- capture supported_jars -%}{%- render 'hx-flavor-support', mode: 'interactive' -%}{%- endcapture -%}\n{%- assign jar_flavors = supported_jars | strip | split: ',' -%}")
s=s.replace("    {%- for view in pilot_views -%}","    {%- assign pilot_views = 'front.webp' | split: ',' -%}\n    {%- if jar_flavors contains flavor -%}{%- assign pilot_views = 'front.webp,left.webp,right.webp' | split: ',' -%}{%- endif -%}\n    {%- for view in pilot_views -%}")
s=s.replace("| downcase | prepend: 'hx-pilot-'","| handleize | prepend: 'hx-pilot-'")
p.write_text(s)
p=ROOT/'snippets/hx-flavor-labels.liquid'
s=p.read_text().replace("{%- assign label_flavors = 'Banana,Blueberry,Mango,Pineapple,Watermelon' | split: ',' -%}","{%- capture supported_labels -%}{%- render 'hx-flavor-support', mode: 'interactive' -%}{%- endcapture -%}\n{%- assign label_flavors = supported_labels | strip | split: ',' -%}").replace("| downcase | prepend: 'hx-label-'","| handleize | prepend: 'hx-label-'")
p.write_text(s)
print('Configured',len(manifest),'fronts and',len(interactive.split(',')),'interactive flavors')
